function wantsBooking(q,a=""){return /когда|подъех|запис|адрес|где|время|график|whatsapp|приех|прием|приём/.test((q+" "+a).toLowerCase())}

async function aiAnswer(message,history,lang="ru"){
  const key=process.env.OPENAI_API_KEY;
  if(!key) return fallback(message,lang);
  const input=[...(Array.isArray(history)?history.slice(-6):[]),{role:"user",content:message}];
  const r=await fetch("https://api.openai.com/v1/responses",{
    method:"POST",
    headers:{"Authorization":"Bearer "+key,"Content-Type":"application/json"},
    body:JSON.stringify({model:"gpt-5.6-luna",instructions:(lang==="kk"?promptKk:promptRu),input,max_output_tokens:420,store:false})
  });
  if(!r.ok){
    const t=await r.text(); console.error("OpenAI",r.status,t.slice(0,500));
    return fallback(message,lang);
  }
  const data=await r.json();
  let answer="";
  for(const item of data.output||[]) for(const c of item.content||[]) if(c.type==="output_text"&&c.text) answer+=c.text;
  answer=answer.trim()||fallback(message,lang).answer;
  return {answer,booking:wantsBooking(message,answer)};
}

function mime(p){
  const ext=path.extname(p).toLowerCase();
  return ({".html":"text/html; charset=utf-8",".css":"text/css; charset=utf-8",".js":"text/javascript; charset=utf-8",".json":"application/json; charset=utf-8",".xml":"application/xml; charset=utf-8",".txt":"text/plain; charset=utf-8",".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".webp":"image/webp",".svg":"image/svg+xml",".ico":"image/x-icon"}[ext]||"application/octet-stream");
}


