function visitorCounterSnippet(lang="ru"){
  const kk=lang==="kk";
  const label=kk?"САЙТҚА КІРУШІЛЕР":"ПОСЕТИТЕЛЕЙ САЙТА";
  const sub=kk?"бірегей браузерлер, есептегіш орнатылған сәттен бастап":"уникальные браузеры с момента установки счётчика";
  const locale=kk?"kk-KZ":"ru-RU";
  return '<section class="site-visitor-counter" aria-label="'+label+'">'+
    '<div class="site-visitor-counter__inner"><span class="site-visitor-counter__label">'+label+'</span>'+
    '<strong class="site-visitor-counter__number" id="siteVisitorCount">…</strong>'+
    '<span class="site-visitor-counter__sub">'+sub+'</span></div></section>'+
    '<style>.site-visitor-counter{padding:16px 4.5%;background:#050505;border-top:1px solid #252525;color:#d8dde8}.site-visitor-counter__inner{max-width:1180px;margin:auto;display:flex;align-items:baseline;justify-content:center;gap:10px;flex-wrap:wrap;text-align:center}.site-visitor-counter__label{font-size:11px;letter-spacing:1.6px;font-weight:800;color:#9fa8b8}.site-visitor-counter__number{font-size:20px;line-height:1;color:#fff;font-weight:900}.site-visitor-counter__sub{font-size:10px;color:#6f7888}</style>'+
    '<script>(function(){var el=document.getElementById("siteVisitorCount");if(!el)return;var k="scanlineVisitorId";var id="";try{id=localStorage.getItem(k)||"";if(!id){id=(crypto&&crypto.randomUUID)?crypto.randomUUID():"v-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2);localStorage.setItem(k,id)}}catch(e){id="v-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2)}fetch("/api/visitor-count",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({visitorId:id}),credentials:"same-origin"}).then(function(r){if(!r.ok)throw new Error("counter");return r.json()}).then(function(d){var n=Number(d&&d.count);el.textContent=Number.isFinite(n)?new Intl.NumberFormat("'+locale+'").format(n):"—"}).catch(function(){el.textContent="—"})})();</script>';
}

async function notFound(req,res){
  const html=await readFile(path.join(__dirname,"404.html"));
  res.writeHead(404,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"});
  return res.end(req.method==="HEAD"?undefined:html);
}
async function readJsonBody(req,limit){
  let body="";for await(const chunk of req){body+=chunk;if(Buffer.byteLength(body)>limit){const e=new Error("Request too large");e.status=413;throw e;}}
  try{return JSON.parse(body||"{}");}catch{const e=new Error("Invalid JSON");e.status=400;throw e;}
}
const server=http.createServer(async(req,res)=>{
  try{
    const url=new URL(req.url,"http://localhost");
    const host=(req.headers.host||"").split(":")[0].toLowerCase();
    if(host==="scanline.kz"){
      res.writeHead(301,{Location:"https://www.scanline.kz"+url.pathname+url.search,"Cache-Control":"no-store"});
      return res.end();
    }
    if(url.pathname==="/favicon.ico"){
      res.writeHead(302,{Location:"/favicon-v3.svg?v=20260923-0905","Cache-Control":"no-store"});
      return res.end();
    }
    const legacyRedirects={
      "/services/kompyuternaya-diagnostika":"/kompyuternaya-diagnostika/",
      "/services/kitayskie-avtomobili":"/diagnostika-kitajskih-avto/",
      "/services/proshivka-kodirovanie":"/proshivka-kodirovanie/",
      "/services/avtosignalizatsiya":"/ustanovka-avtosignalizacii/",
      "/services/gps-mayachki":"/gps-mayaki/",
      "/services/remont-avtoelektriki":"/remont-avtoelektriki/"
    };
    const normalizedPath=(url.pathname.length>1 && url.pathname.endsWith("/")) ? url.pathname.slice(0,-1) : url.pathname;
    if(legacyRedirects[normalizedPath]){
      res.writeHead(301,{Location:legacyRedirects[normalizedPath],"Cache-Control":"public, max-age=86400"});
      return res.end();
    }
    if(req.method==="POST"&&url.pathname==="/api/visitor-count"){
      try{
        const data=await readJsonBody(req,2048);
        const visitorId=String(data.visitorId||"").trim();
        if(!/^[A-Za-z0-9._:-]{10,128}$/.test(visitorId)) return json(res,400,{error:"Invalid visitor id"});
        const supabaseUrl=String(process.env.SUPABASE_URL||"").replace(/\/$/,"");
        const supabaseKey=String(process.env.SUPABASE_PUBLISHABLE_KEY||"");
        if(!supabaseUrl||!supabaseKey) return json(res,503,{error:"Counter unavailable"});
        const sr=await fetch(supabaseUrl+"/rest/v1/rpc/increment_scanline_visitor",{
          signal:AbortSignal.timeout(8000),
          method:"POST",
          headers:{"Content-Type":"application/json","apikey":supabaseKey,"Authorization":"Bearer "+supabaseKey},
          body:JSON.stringify({p_visitor_id:visitorId})
        });
        if(!sr.ok) return json(res,502,{error:"Counter backend error"});
        const raw=await sr.text();
        let count;
        try{count=Number(JSON.parse(raw))}catch{count=Number(raw)}
        if(!Number.isFinite(count)) return json(res,502,{error:"Counter response error"});
        return json(res,200,{count});
      }catch(e){
        console.error("visitor counter",e);
        return json(res,e.status||500,{error:e.status?e.message:"Counter error"});
      }
    }
    if(req.method==="POST"&&url.pathname==="/api/chat"){
      const ip=(req.headers["x-forwarded-for"]||req.socket.remoteAddress||"").toString().split(",")[0].trim();
      const now=Date.now(),last=rate.get(ip)||0;
      if(rate.size>5000)rate.delete(rate.keys().next().value);
      if(now-last<1200) return json(res,429,{error:"Слишком часто. Подождите секунду."});
      rate.set(ip,now);
      const data=await readJsonBody(req,24000);
      const message=String(data.message||"").trim().slice(0,600);
      if(!message) return json(res,400,{error:"Введите вопрос."});
      const out=await aiAnswer(message,data.history,String(data.lang||"ru").toLowerCase().startsWith("kk")?"kk":"ru");
      return json(res,200,{...out,whatsapp:WHATSAPP});
    }
    if(req.method!=="GET"&&req.method!=="HEAD"){res.writeHead(405);return res.end("Method Not Allowed")}
    if(url.pathname==="/kk" || url.pathname==="/kk/" || url.pathname.startsWith("/kk/")){
      const requestedKkPath=url.pathname==="/kk"?"/kk/":url.pathname;
      const ruPath=kkRuPath(requestedKkPath);
      if(kkPages[ruPath]){
        const html=kkPageHtml(kkPages[ruPath],ruPath).replace("</head>",responsiveAuditCss()+"</head>").replace("</body>",visitorCounterSnippet("kk")+"</body>").replaceAll("https://scanline.kz/","https://www.scanline.kz/");
        res.writeHead(200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store, no-cache, must-revalidate","Content-Language":"kk-KZ"});
        if(req.method==="HEAD") return res.end();
        return res.end(html);
      }
      return await notFound(req,res);
    }
    let rel=decodeURIComponent(url.pathname);
    if(rel.endsWith("/")) rel+="index.html";
    let file=path.resolve(__dirname,"."+rel);
    if(!file.startsWith(__dirname+path.sep)){res.writeHead(403);return res.end("Forbidden")}
    const allowedExtensions=new Set([".html",".css",".js",".svg",".png",".jpg",".jpeg",".webp",".gif",".ico",".woff",".woff2",".ttf",".txt",".xml",".pdf",".mp4"]);
    if(rel.split("/").some(part=>part.startsWith(".")) || (path.extname(file) && !allowedExtensions.has(path.extname(file).toLowerCase())) || ["package.json","package-lock.json","CNAME","README.md"].includes(path.basename(file))){res.writeHead(404);return res.end("Not Found")}
    try{
      const st=await stat(file);
      if(st.isDirectory()){
        file=path.join(file,"index.html");
      }
      let buf=await readFile(file);
      const contentType=mime(file);
      if(["sitemap.xml","sitemap.txt","robots.txt"].includes(path.basename(file)))buf=Buffer.from(buf.toString("utf8").replaceAll("https://scanline.kz/","https://www.scanline.kz/"));
      if(path.extname(file).toLowerCase()===".html"){
        const ruKey=url.pathname==="/"?"/":(url.pathname.endsWith("/")?url.pathname:url.pathname+"/");
        let html=buf.toString("utf8");
        if(/<meta[^>]+name=["']viewport["']/i.test(html)){
          html=html.replace(/<meta([^>]+)name=["']viewport["']([^>]+)content=["'][^"']*["']([^>]*)>/i,'<meta$1name="viewport"$2content="width=device-width,initial-scale=1,viewport-fit=cover"$3>');
        }else{
          html=html.replace("</head>",'<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"></head>');
        }
        html=html.replace(/\/lang\.js\?v=[^"'<> ]+/g,"/lang.js?v=20260923-mobile-audit2");
        html=html.replace(/\/lang\.css\?v=[^"'<> ]+/g,"/lang.css?v=20260923-mobile-audit2");
        if(!/\/lang\.css/i.test(html)){
          html=html.replace("</head>",'<link rel="stylesheet" href="/lang.css?v=20260923-mobile-audit2"></head>');
        }
        if(!/\/lang\.js/i.test(html)){
          html=html.replace("</head>",'<script defer src="/lang.js?v=20260923-mobile-audit2"></script></head>');
        }
        if(kkPages[ruKey]){
          html=html.replace("</head>",hreflangTagsForRu(ruKey)+"</head>");
        }
        if(!html.includes("scanline-responsive-audit")){
          html=html.replace("</head>",responsiveAuditCss()+"</head>");
        }
        if(!html.includes("site-visitor-counter")){
          html=html.replace("</body>",visitorCounterSnippet("ru")+"</body>");
        }
        buf=Buffer.from(html.replaceAll("https://scanline.kz/","https://www.scanline.kz/"),"utf8");
      }
      res.writeHead(200,{"Content-Type":contentType,"Cache-Control":"no-store, no-cache, must-revalidate","Content-Language":"ru-KZ"});
      if(req.method==="HEAD") return res.end();
      return res.end(buf);
    }catch{
      return await notFound(req,res);
    }
  }catch(e){
    console.error(e); json(res,e.status||((e instanceof URIError)?400:500),{error:e.status?e.message:"Server error"});
  }
});
server.listen(PORT,"0.0.0.0",()=>console.log("ScanLine server listening on",PORT));